#!/bin/bash
# Session 32 - Generation Script
# Focus: M3-generated wild genre fusions, new experimental territory
# "The AI dreams up its own music"

set -e
cd /home/eileen/projects/ai-writings/music/mmx-session32
OUTDIR="."

echo "=== Session 32 Generation ==="
echo "Start: $(date)"
echo ""

# ============================================================
# EXPERIMENT 1: M3-Generated Wild Genre Fusions
# Prompts and lyrics generated by MiniMax-M3 at temperature 0.9
# Tests whether an LLM's musical imagination translates to good generation
# ============================================================

echo "--- Experiment 1: M3 Wild Fusions ---"

# 1. Celestial Jazz-Hop with Gregorian Chants
cat > celestial-lyrics.txt << 'LYRICS'
[Intro: Gregorian chant layered over lo-fi vinyl crackle]
Veni, veni, lumen noctis

[Verse 1]
Midnight pours like whiskey through the stained glass
Monks trading prayers for brass time moves slow then fast
My saxophone confessions to a God on the phone
She said child you ain't alone just don't come home

[Chorus]
We're dancing in the nave where the shadows pray
808s confessing what the organ couldn't say
Heaven's got a hi-hat hell's got the bass
We're floating in between in this liminal space

[Verse 2]
The cathedral roof is painted like the night sky
But the stars are cigarette burns from some other life
I kneel at the altar of the Rhodes piano
Praying to the ghost of Coltrane and the concept of tomorrow

[Chorus]
We're dancing in the nave where the shadows pray
808s confessing what the organ couldn't say
Heaven's got a hi-hat hell's got the bass
We're floating in between in this liminal space

[Bridge]
Gloria in excelsis yeah I know I'm blessed
Bow down to the beat bow down to the west
The monks are in the booth and they're mixing something sacred
The sermon is a sample and the sample is faded

[Outro]
Veni veni lumen noctis
The light comes in through the crack in the door
The light comes in
The light
LYRICS

echo "Generating: Celestial Jazz-Hop..."
mmx music generate \
  --prompt "Nocturnal jazz-hop fusion with Gregorian monks chanting in Latin, smoky 1940s saxophone, booming 808 trap drums, crisp hi-hats, dreamy Rhodes piano, cathedral atmosphere, trip-hop at 72 BPM" \
  --lyrics-file celestial-lyrics.txt \
  --bpm 72 \
  --key "D minor" \
  --out "${OUTDIR}/m3-01-celestial-jazz-hop.mp3" \
  --quiet --yes 2>/dev/null && \
  echo "  ✓ m3-01-celestial-jazz-hop.mp3 ($(stat -c%s ${OUTDIR}/m3-01-celestial-jazz-hop.mp3) bytes)" || \
  echo "  ✗ m3-01 FAILED"

# 2. Quantum Disco-Flamenco
cat > quantum-lyrics.txt << 'LYRICS'
[Verse 1]
Lime light bleeding through the cigarette smoke
Your heels click like code that my heart can't revoke
Ole to the algorithm ole to the flame
I'm dancing with your memory forgetting your name

[Pre-chorus]
Castanets like bullets sequins catch the laser
Every wound you left me became my own raiser

[Chorus]
Baila in the quantum of the night
Every step collapses to a parallel light
Synthwave matador with electric roses
I'm the saint and the sinner the disco imposes

[Verse 2]
Neon bulls charge through a hologram arena
Your shadow on the wall dressed in verbena
The guitar builds a ladder to a constellation
I climb and find you waiting at every station

[Chorus]
Baila in the quantum of the night
Every step collapses to a parallel light
Synthwave matador with electric roses
I'm the saint and the sinner the disco imposes

[Bridge]
The disco ball is a hadron collider
Every spark a particle getting wider
Flamenco in the multiverse forever
Every version of us dancing together

[Outro]
Ole ole ole
The light collapses
The music stays
LYRICS

echo "Generating: Quantum Disco-Flamenco..."
mmx music generate \
  --prompt "Pulsing neon-drenched dancefloor, traditional Spanish flamenco guitars with euphoric synthwave arpeggios, driving house basslines, rapid-fire castanet patterns, tempo shifts between 90 and 130 BPM, disco-flamenco fusion" \
  --lyrics-file quantum-lyrics.txt \
  --bpm 120 \
  --key "A minor" \
  --out "${OUTDIR}/m3-02-quantum-disco-flamenco.mp3" \
  --quiet --yes 2>/dev/null && \
  echo "  ✓ m3-02-quantum-disco-flamenco.mp3 ($(stat -c%s ${OUTDIR}/m3-02-quantum-disco-flamenco.mp3) bytes)" || \
  echo "  ✗ m3-02 FAILED"

# 3. Apocalyptic Polka-Punk
cat > polka-lyrics.txt << 'LYRICS'
[Verse 1]
Baba Yaga's driving the tank comrade hold your beer
The borders are melting the bureaucracy's unclear
Polka in the ashes accordion on fire
We're waltzing through the wreckage of the entire empire

[Chorus]
Uno dos tres the world is on its knees
Strike up the brass band boys do it please
Burn the manifestos dance upon the page
This is the last polka of the final age

[Verse 2]
The accordion player lost three fingers to the frost
But the melody is perfect when you count the cost
Tuba players marching through the radiation snow
The rhythm section's glowing but they're ready to go

[Chorus]
Uno dos tres the world is on its knees
Strike up the brass band boys do it please
Burn the manifestos dance upon the page
This is the last polka of the final age

[Bridge]
I wrote a love letter in Morse code to the moon
The moon replied in Polish said I'll see you soon
