The light returns
The light returns
The light
LYRICS

echo "Generating: With structure tags..."
mmx music generate \
  --prompt "Nordic folk, fingerpicked acoustic guitar, ambient drone, reverb, cinematic, melancholic" \
  --lyrics-file struct-standard.txt \
  --bpm 80 \
  --key "D minor" \
  --out "${OUTDIR}/structure-with-tags.mp3" \
  --quiet --yes 2>/dev/null && \
  echo "  ✓ structure-with-tags.mp3 ($(stat -c%s ${OUTDIR}/structure-with-tags.mp3) bytes)" || \
  echo "  ✗ with-tags FAILED"

echo "Generating: Without structure tags..."
mmx music generate \
  --prompt "Nordic folk, fingerpicked acoustic guitar, ambient drone, reverb, cinematic, melancholic" \
  --lyrics-file struct-none.txt \
  --bpm 80 \
  --key "D minor" \
  --out "${OUTDIR}/structure-no-tags.mp3" \
  --quiet --yes 2>/dev/null && \
  echo "  ✓ structure-no-tags.mp3 ($(stat -c%s ${OUTDIR}/structure-no-tags.mp3) bytes)" || \
  echo "  ✗ no-tags FAILED"

# ============================================================
# EXPERIMENT 4: Seed-based reproducibility test (cover)
# Same cover prompt + audio, different seeds
# ============================================================

echo ""
echo "--- Experiment 4: Cover Seed Study ---"

# Find a good source track
SRC=""
for candidate in ../mmx-session28/62-the-tensor-shoegaze-cover-of-cover.mp3 ../05-genre-matrix-synthwave.mp3 ../59-astral-drone-folk.mp3; do
  [ -f "$candidate" ] && SRC="$candidate" && break
done

if [ -n "$SRC" ]; then
  for seed in 42 1337 99999; do
    echo "Generating cover with seed ${seed}..."
    mmx music cover \
      --prompt "Lo-fi indie rock, jangly guitars, soft drums, warm bass, melancholic male vocal" \
      --audio-file "$SRC" \
      --seed $seed \
      --out "${OUTDIR}/cover-seed-${seed}.mp3" \
      --quiet --yes 2>/dev/null && \
      echo "  ✓ cover-seed-${seed}.mp3 ($(stat -c%s ${OUTDIR}/cover-seed-${seed}.mp3) bytes)" || \
      echo "  ✗ seed-${seed} FAILED"
  done
else
  echo "  No source track found, skipping"
fi

echo ""
echo "=== Session 32 Complete ==="
echo "End: $(date)"
echo ""
echo "=== Results Summary ==="
for f in ${OUTDIR}/*.mp3; do
  [ -f "$f" ] || continue
  size=$(stat -c%s "$f")
  duration_s=$((size / 32000))
  echo "$(basename $f): ${duration_s}s, $(python3 -c "print(f'{$size/1048576:.1f}')")MB"
done
